.xd6-service-sidebar__item:last-child{padding-bottom:0}.xd6-service-sidebar__item img{flex:0 0 64px;width:64px;height:56px;object-fit:cover;border-radius:5px}.xd6-service-sidebar__item span{min-width:0}
